export function getCategories(): string[] {
  return [...CATEGORIES];
}

export function getPromptsByCategory(category: string): string[] {
  return CATEGORY_PROMPTS[category] || [];
}

export function getAllPrompts(): { id: number; prompt: string; category: string }[] {
  const prompts: { id: number; prompt: string; category: string }[] = [];
  let id = 1;
  for (const [category, list] of Object.entries(CATEGORY_PROMPTS)) {
    for (const prompt of list) {
      prompts.push({ id: id++, prompt, category });
    }
  }
  return prompts;
}

export function getTotalPromptCount(): number {
  return getAllPrompts().length;
}
